//! List item markers: ordinal strings (`decimal`, `lower-roman`, …) and the
//! placement of `outside` markers left of the first line box.
//!
//! `inside` markers are generated by box construction as inline content at
//! the start of the list item (see [`inside_marker_text`]); `outside`
//! markers become the [`ListMarker`] of the list item's box.

use xbro_style::{ListStylePosition, ListStyleType};

use crate::box_tree::BoxNode;
use crate::cx::LayoutCx;
use crate::geom::Rect;
use crate::sizing::sane_size;
use crate::{LayoutBox, ListMarker, MarkerContent, TextFragment};

/// Gap between an outside marker and the list item's content, in em.
const MARKER_GAP_EM: f32 = 0.5;

/// Diameter of disc/circle/square bullets, in em.
const BULLET_EM: f32 = 0.33;

/// Largest size of a `list-style-image` marker, in px.
const MAX_MARKER_IMAGE: f32 = 1000.0;

/// Bijective base-`n` representation of `v >= 1` using `digits`.
fn alphabetic(mut v: i64, digits: &[char]) -> String {
    let n = digits.len() as i64;
    let mut out = Vec::new();
    while v > 0 && out.len() < 32 {
        v -= 1;
        let d = usize::try_from(v % n).unwrap_or(0);
        out.push(digits.get(d).copied().unwrap_or('?'));
        v /= n;
    }
    out.iter().rev().collect()
}

/// Roman numeral of `1..=3999`.
fn roman(mut v: i64, upper: bool) -> String {
    const TABLE: [(i64, &str); 13] = [
        (1000, "m"),
        (900, "cm"),
        (500, "d"),
        (400, "cd"),
        (100, "c"),
        (90, "xc"),
        (50, "l"),
        (40, "xl"),
        (10, "x"),
        (9, "ix"),
        (5, "v"),
        (4, "iv"),
        (1, "i"),
    ];
    let mut out = String::new();
    for &(n, s) in &TABLE {
        while v >= n {
            out.push_str(s);
            v -= n;
        }
    }
    if upper {
        out.to_ascii_uppercase()
    } else {
        out
    }
}

/// The counter representation of `ordinal` for an ordinal list style
/// (without the trailing ". "), or `None` for bullets and `none`.
pub(crate) fn counter_text(ty: ListStyleType, ordinal: i64) -> Option<String> {
    const LATIN: [char; 26] = [
        'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r',
        's', 't', 'u', 'v', 'w', 'x', 'y', 'z',
    ];
    const GREEK: [char; 24] = [
        'α', 'β', 'γ', 'δ', 'ε', 'ζ', 'η', 'θ', 'ι', 'κ', 'λ', 'μ', 'ν', 'ξ', 'ο', 'π', 'ρ', 'σ',
        'τ', 'υ', 'φ', 'χ', 'ψ', 'ω',
    ];
    let decimal = || ordinal.to_string();
    Some(match ty {
        ListStyleType::Disc
        | ListStyleType::Circle
        | ListStyleType::Square
        | ListStyleType::None => return None,
        ListStyleType::Decimal => decimal(),
        ListStyleType::DecimalLeadingZero => {
            if (0..10).contains(&ordinal) {
                format!("0{ordinal}")
            } else if (-9..0).contains(&ordinal) {
                format!("-0{}", -ordinal)
            } else {
                decimal()
            }
        }
        ListStyleType::LowerAlpha | ListStyleType::UpperAlpha if ordinal >= 1 => {
            let s = alphabetic(ordinal, &LATIN);
            if ty == ListStyleType::UpperAlpha {
                s.to_uppercase()
            } else {
                s
            }
        }
        ListStyleType::LowerRoman | ListStyleType::UpperRoman if (1..=3999).contains(&ordinal) => {
            roman(ordinal, ty == ListStyleType::UpperRoman)
        }
        ListStyleType::LowerGreek if ordinal >= 1 => alphabetic(ordinal, &GREEK),
        // Out of range for the style: fall back to decimal.
        _ => decimal(),
    })
}

/// Marker string of an ordinal list style ("1.", "iv.", "b.").
pub(crate) fn marker_text(ty: ListStyleType, ordinal: i64) -> Option<String> {
    counter_text(ty, ordinal).map(|s| format!("{s}."))
}

/// Text of an `inside` marker, laid out as inline content: the marker
/// followed by a space (bullets use their Unicode characters).
pub(crate) fn inside_marker_text(ty: ListStyleType, ordinal: i64) -> Option<String> {
    match ty {
        ListStyleType::None => None,
        ListStyleType::Disc => Some("\u{2022}\u{A0}".to_string()),
        ListStyleType::Circle => Some("\u{25E6}\u{A0}".to_string()),
        ListStyleType::Square => Some("\u{25AA}\u{A0}".to_string()),
        _ => marker_text(ty, ordinal).map(|s| format!("{s}\u{A0}")),
    }
}

impl<'t> LayoutCx<'t> {
    /// Outside marker of a laid-out list item (`None` for inside markers,
    /// `list-style-type: none` without image, or anonymous boxes).
    pub fn list_marker(&mut self, b: &BoxNode, lb: &LayoutBox) -> Option<ListMarker> {
        let style = &b.style;
        if style.list_style_position == ListStylePosition::Inside {
            return None;
        }
        let node = b.node?;
        let font = self.font(style);
        let em = font.size;
        let baseline =
            crate::tree::first_baseline(lb).unwrap_or(lb.content.y + font.above.max(0.0));
        let right = lb.content.x - MARKER_GAP_EM * em;
        let color = style.color;

        if let Some(url) = &style.list_style_image {
            if let Some(s) = self.replaced.url_size(url) {
                if s.width.is_finite() && s.height.is_finite() {
                    let w = sane_size(s.width).min(MAX_MARKER_IMAGE);
                    let h = sane_size(s.height).min(MAX_MARKER_IMAGE);
                    return Some(ListMarker {
                        rect: Rect::new(right - w, baseline - h, w, h),
                        color,
                        content: MarkerContent::Image(url.to_string()),
                    });
                }
            }
        }

        let ordinal = b.ordinal.unwrap_or(1);
        let bullet = |content: MarkerContent| {
            let d = BULLET_EM * em;
            let cy = baseline - font.metrics.x_height.max(0.0) / 2.0;
            ListMarker {
                rect: Rect::new(right - d, cy - d / 2.0, d, d),
                color,
                content,
            }
        };
        match style.list_style_type {
            ListStyleType::None => None,
            ListStyleType::Disc => Some(bullet(MarkerContent::Disc)),
            ListStyleType::Circle => Some(bullet(MarkerContent::Circle)),
            ListStyleType::Square => Some(bullet(MarkerContent::Square)),
            ty => {
                let text = marker_text(ty, ordinal)?;
                let ls = crate::sizing::sane(style.letter_spacing);
                let shaped = self.fonts.shape(font.id, font.size, &text, ls, 0.0);
                let width = sane_size(shaped.width);
                let ascent = font.ascent();
                let rect = Rect::new(
                    right - width,
                    baseline - ascent,
                    width,
                    ascent + font.descent(),
                );
                Some(ListMarker {
                    rect,
                    color,
                    content: MarkerContent::Text(TextFragment {
                        node,
                        rect,
                        baseline,
                        text,
                        font: font.id,
                        font_size: font.size,
                        glyphs: shaped.glyphs,
                        style: style.clone(),
                    }),
                })
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ordinals() {
        use ListStyleType::*;
        assert_eq!(marker_text(Decimal, 3).as_deref(), Some("3."));
        assert_eq!(marker_text(Decimal, -2).as_deref(), Some("-2."));
        assert_eq!(marker_text(DecimalLeadingZero, 7).as_deref(), Some("07."));
        assert_eq!(marker_text(DecimalLeadingZero, 12).as_deref(), Some("12."));
        assert_eq!(marker_text(LowerAlpha, 1).as_deref(), Some("a."));
        assert_eq!(marker_text(LowerAlpha, 26).as_deref(), Some("z."));
        assert_eq!(marker_text(LowerAlpha, 27).as_deref(), Some("aa."));
        assert_eq!(marker_text(UpperAlpha, 28).as_deref(), Some("AB."));
        assert_eq!(marker_text(LowerAlpha, 0).as_deref(), Some("0."));
        assert_eq!(marker_text(LowerRoman, 4).as_deref(), Some("iv."));
        assert_eq!(marker_text(UpperRoman, 1994).as_deref(), Some("MCMXCIV."));
        assert_eq!(marker_text(UpperRoman, 4000).as_deref(), Some("4000."));
        assert_eq!(marker_text(LowerGreek, 1).as_deref(), Some("α."));
        assert_eq!(marker_text(LowerGreek, 25).as_deref(), Some("αα."));
        assert_eq!(marker_text(Disc, 1), Option::None);
        assert_eq!(marker_text(None, 1), Option::None);
        assert_eq!(
            marker_text(LowerAlpha, i64::MAX).map(|s| s.len() < 40),
            Some(true)
        );
    }

    #[test]
    fn inside_texts() {
        use ListStyleType::*;
        assert_eq!(
            inside_marker_text(Disc, 1).as_deref(),
            Some("\u{2022}\u{A0}")
        );
        assert_eq!(inside_marker_text(Decimal, 2).as_deref(), Some("2.\u{A0}"));
        assert_eq!(inside_marker_text(None, 2), Option::None);
    }
}
